#!/usr/bin/env bash
# Rebuilds all figures from the shipped caches and checks the numbers quoted in the text. Takes about a minute; needs no GPU, no qsdl, no Blender, no hardware.
#   ./reproduce.sh                 (PY=<python with numpy, scipy, matplotlib> to override the interpreter)
# Steps: (1) the power-law slopes of Fig. 4(a) against results/expected_numbers.txt, (2) all figures, (3) the recorded outputs in results/, (4) with --full the
# 60-network cache of Fig. 3(b) is regenerated by panel_b_big.py and compared with the shipped file. Any difference gives exit code 1.
set -euo pipefail
ROOT="$(cd "$(dirname "$(readlink -f "$0")")" && pwd)"; cd "$ROOT"
PY="${PY:-python3}"
"$PY" -c "import numpy, scipy, matplotlib" || { echo "ERROR: $PY lacks numpy/scipy/matplotlib"; exit 2; }
LOG="$(mktemp)"; trap 'rm -f "$LOG"' EXIT
echo "== 1 slopes of Fig. 4(a)"
"$PY" part2/fixes_figures.py | tee "$LOG"
GOT="$(grep -h 'slopes' "$LOG" | head -1 | sed 's/^ *//')"; WANT="$(head -1 results/expected_numbers.txt)"
if [ "$GOT" = "$WANT" ]; then echo "OK: $GOT"; else echo "MISMATCH"; echo "  got : $GOT"; echo "  want: $WANT"; exit 1; fi
echo "== 2 all figures"
"$PY" part2/fig_redesign.py > /dev/null
echo "== 3 recorded outputs"
for c in check_mindist check_nonlinear_code check5_rm_decoder capacity_summary; do
  "$PY" part2/$c.py > "$LOG.$c" 2>&1
  if diff -q "$LOG.$c" results/$c.txt > /dev/null; then echo "OK: $c"; else echo "MISMATCH: $c"; diff "$LOG.$c" results/$c.txt | head -5; exit 1; fi
  rm -f "$LOG.$c"
done
"$PY" part2/qrc_benchmark.py 2>&1 | sed 1d > "$LOG.q"
if diff -q "$LOG.q" results/qrc_benchmark.txt > /dev/null; then echo "OK: qrc_benchmark"; else echo "MISMATCH: qrc_benchmark"; exit 1; fi
rm -f "$LOG.q"
if [ "${1:-}" = "--full" ]; then
  echo "== 5 regeneration of the Fig. 3(b) cache (about 4 minutes)"
  TMPNPZ="$(mktemp -u).npz"
  "$PY" part2/panel_b_big.py --out "$TMPNPZ" > /dev/null
  "$PY" - "$TMPNPZ" <<'PYC'
import sys, numpy as np
a = np.load(sys.argv[1], allow_pickle=True); b = np.load("figures/data/fix_panel_b_big.npz", allow_pickle=True)
assert sorted(a.files) == sorted(b.files), "different keys"
for k in a.files: assert np.array_equal(a[k], b[k]), "differs: " + k
print("OK: panel_b_big.py reproduces fix_panel_b_big.npz bit for bit")
PYC
  rm -f "$TMPNPZ"
  echo "== 6 six independent redraws of the cell n = 8, L = 3, f = 0.1875 (about 1.5 minutes)"
  cp results/redraw_panel_b.json "$LOG.rd.old"
  "$PY" part2/redraw_panel_b.py > "$LOG.rd" 2>&1
  if cmp -s results/redraw_panel_b.json "$LOG.rd.old"; then echo "OK: redraw_panel_b.py reproduces results/redraw_panel_b.json"; else echo "MISMATCH: redraw_panel_b"; exit 1; fi
  rm -f "$LOG.rd" "$LOG.rd.old"
fi
